fn alef_bridge_error_tenant_error(message: String, e: &hacienda::tenancy::TenantError) -> AlefBridgeError {
    let mut payload = std::collections::BTreeMap::new();
    let kind = match e {
        hacienda::tenancy::TenantError::AlreadyExists(_) => "AlreadyExists",
        hacienda::tenancy::TenantError::NotFound(_) => "NotFound",
        hacienda::tenancy::TenantError::Internal(__alef_field_0) => {
            if let Ok(value) = serde_json::to_string(__alef_field_0) {
                payload.insert("_0".to_string(), value);
            }
            "Internal"
        }
        _ => "",
    };
    AlefBridgeError {
        message,
        error_type: "TenantError".to_string(),
        kind: kind.to_string(),
        payload,
        status: -1,
        retry_after_ms: -1,
    }
}

/// Build the bridge error for `error`. The core error types give their kind, status and retry
/// delay, also when a stream or a boxed error holds them; any other error gives its message only.
pub fn alef_bridge_error<E: std::fmt::Display + 'static>(error: E) -> AlefBridgeError {
    let message = error.to_string();
    let any: &dyn std::any::Any = &error;
    let boxed_sync = any.downcast_ref::<Box<dyn std::error::Error + Send + Sync + 'static>>();
    let boxed = any.downcast_ref::<Box<dyn std::error::Error + 'static>>();
    if let Some(e) = any.downcast_ref::<hacienda::jobs::JobError>() {
        return alef_bridge_error_job_error(message, e);
    }
    if let Some(e) = boxed_sync.and_then(|b| b.downcast_ref::<hacienda::jobs::JobError>()) {
        return alef_bridge_error_job_error(message, e);
    }
    if let Some(e) = boxed.and_then(|b| b.downcast_ref::<hacienda::jobs::JobError>()) {
        return alef_bridge_error_job_error(message, e);
    }
    if let Some(e) = any.downcast_ref::<hacienda::store::object::ObjectStoreError>() {
        return alef_bridge_error_object_store_error(message, e);
    }
    if let Some(e) = boxed_sync.and_then(|b| b.downcast_ref::<hacienda::store::object::ObjectStoreError>()) {
        return alef_bridge_error_object_store_error(message, e);
    }
    if let Some(e) = boxed.and_then(|b| b.downcast_ref::<hacienda::store::object::ObjectStoreError>()) {
        return alef_bridge_error_object_store_error(message, e);
    }
    if let Some(e) = any.downcast_ref::<hacienda::tenancy::TenantError>() {
        return alef_bridge_error_tenant_error(message, e);
    }
    if let Some(e) = boxed_sync.and_then(|b| b.downcast_ref::<hacienda::tenancy::TenantError>()) {
        return alef_bridge_error_tenant_error(message, e);
    }
    if let Some(e) = boxed.and_then(|b| b.downcast_ref::<hacienda::tenancy::TenantError>()) {
        return alef_bridge_error_tenant_error(message, e);
    }
    let _ = (boxed_sync, boxed);
    AlefBridgeError::from(message)
}

