pub struct ArchiveMetadata(pub xberg::ArchiveMetadata);
impl ArchiveMetadata {
    pub fn new(
        format: String,
        file_count: u32,
        file_list: Vec<String>,
        total_size: u64,
        compressed_size: Option<u64>,
    ) -> ArchiveMetadata {
        let mut __target: xberg::ArchiveMetadata = ::std::default::Default::default();
        {
            // Try JSON parse first (handles enum/object values); on parse failure
            // treat the raw input as a JSON string scalar so plain `String` /
            // string-like enum fields don't end up empty for inputs that aren't
            // valid JSON tokens (e.g. `tts-1`).
            let __v = ::serde_json::from_str::<::serde_json::Value>(&format)
                .unwrap_or(::serde_json::Value::String(format.clone()));
            if let Ok(t) = ::serde_json::from_value(__v) {
                __target.format = t;
            }
        }
        __target.file_count = file_count;
        if let Ok(__v) = ::serde_json::to_value(file_list) {
            if let Ok(t) = ::serde_json::from_value(__v) {
                __target.file_list = t;
            }
        }
        __target.total_size = total_size;
        __target.compressed_size = compressed_size;
        ArchiveMetadata(__target)
    }
    pub fn format(&self) -> String {
        self.0.format.to_string()
    }
    pub fn file_count(&self) -> u32 {
        ::serde_json::to_value(&self.0.file_count)
            .ok()
            .and_then(|j| ::serde_json::from_value(j).ok())
            .unwrap_or_default()
    }
    pub fn file_list(&self) -> Vec<String> {
        ::serde_json::to_value(&self.0.file_list)
            .ok()
            .and_then(|j| ::serde_json::from_value(j).ok())
            .unwrap_or_default()
    }
    pub fn total_size(&self) -> u64 {
        ::serde_json::to_value(&self.0.total_size)
            .ok()
            .and_then(|j| ::serde_json::from_value(j).ok())
            .unwrap_or_default()
    }
    pub fn compressed_size(&self) -> Option<u64> {
        self.0.compressed_size.as_ref().and_then(|v| {
            ::serde_json::to_value(v)
                .ok()
                .and_then(|j| ::serde_json::from_value(j).ok())
        })
    }
}

