pub struct ModelConfig(pub hacienda::pii::ModelConfig);
impl ModelConfig {
    pub fn new(
        enabled: bool,
        model_dir: Option<String>,
        model_id: Option<String>,
        lora_adapter_dir: Option<String>,
    ) -> ModelConfig {
        let mut __target: hacienda::pii::ModelConfig = ::std::default::Default::default();
        __target.enabled = enabled;
        if let Some(s) = model_dir {
            // Try JSON parse first (handles enum/object values); on parse failure
            // treat the raw input as a JSON string scalar so plain `String` /
            // string-like enum fields don't end up empty for inputs that aren't
            // valid JSON tokens (e.g. `tts-1`).
            let __v = ::serde_json::from_str::<::serde_json::Value>(&s).unwrap_or(::serde_json::Value::String(s));
            if let Ok(t) = ::serde_json::from_value(__v) {
                __target.model_dir = Some(t);
            }
        }
        if let Some(value) = model_id {
            __target.model_id = Some(value);
        }
        if let Some(s) = lora_adapter_dir {
            // Try JSON parse first (handles enum/object values); on parse failure
            // treat the raw input as a JSON string scalar so plain `String` /
            // string-like enum fields don't end up empty for inputs that aren't
            // valid JSON tokens (e.g. `tts-1`).
            let __v = ::serde_json::from_str::<::serde_json::Value>(&s).unwrap_or(::serde_json::Value::String(s));
            if let Ok(t) = ::serde_json::from_value(__v) {
                __target.lora_adapter_dir = Some(t);
            }
        }
        ModelConfig(__target)
    }
    pub fn enabled(&self) -> bool {
        ::serde_json::to_value(&self.0.enabled)
            .ok()
            .and_then(|j| ::serde_json::from_value(j).ok())
            .unwrap_or_default()
    }
    pub fn model_dir(&self) -> Option<String> {
        self.0.model_dir.as_ref().map(|v| v.to_string_lossy().into_owned())
    }
    pub fn model_id(&self) -> Option<String> {
        self.0.model_id.clone()
    }
    pub fn lora_adapter_dir(&self) -> Option<String> {
        self.0
            .lora_adapter_dir
            .as_ref()
            .map(|v| v.to_string_lossy().into_owned())
    }
}

