pub struct NerDetector(pub hacienda::pii::NerDetector);

pub fn ner_detector_runtime_state(client: &NerDetector) -> NerRuntimeState {
    NerRuntimeState(client.0.runtime_state())
}
pub fn ner_detector_with_threshold(client: &NerDetector, threshold: f32) -> NerDetector {
    NerDetector(client.0.clone().with_threshold(threshold))
}
pub async fn ner_detector_detect(client: &NerDetector, text: String) -> Result<Vec<ModelEntity>, AlefBridgeError> {
    // SAFETY: Swift keeps the receiver alive until this future's task completes.
    let client: &'static NerDetector = unsafe { &*(client as *const NerDetector) };
    let __alef_task = crate::__alef_tokio_runtime().spawn(async move {
        client
            .0
            .detect(&text)
            .await
            .map_err(alef_bridge_error)
            .map(|vec| vec.into_iter().map(ModelEntity).collect())
    });
    __alef_task.await.unwrap_or_else(|__alef_join_error| {
        Err(AlefBridgeError::from(format!(
            "alef: spawned async task failed: {__alef_join_error}"
        )))
    })
}

